package inventory

import (
  "context"
  "database/sql"

  "google.golang.org/grpc/codes"
  "google.golang.org/grpc/status"

  inventorypb "example.com/shop/gen/inventory/v1"
)

type Server struct {
  inventorypb.UnimplementedInventoryServiceServer
  db *sql.DB
}

func (s *Server) Reserve(ctx context.Context, req *inventorypb.ReserveRequest) (*inventorypb.ReserveResponse, error) {
  res, err := s.db.ExecContext(context.Background(),
    "UPDATE stock SET quantity = quantity - $1 WHERE sku = $2 AND quantity >= $1",
    req.GetQuantity(), req.GetSku())
  if err != nil {
    return nil, err
  }
  n, err := res.RowsAffected()
  if err != nil {
    return nil, err
  }
  if n == 0 {
    return nil, status.Error(codes.FailedPrecondition, "out of stock")
  }
  return &inventorypb.ReserveResponse{}, nil
}

