package checkout

import (
  "context"
  "errors"
  "time"

  "google.golang.org/grpc/codes"
  "google.golang.org/grpc/status"

  inventorypb "example.com/shop/gen/inventory/v1"
)

var (
  ErrOutOfStock       = errors.New("out of stock")
  ErrInventoryTimeout = errors.New("inventory timed out")
)

type Service struct {
  inv inventorypb.InventoryServiceClient
}

func (s *Service) Reserve(ctx context.Context, sku string, qty int32) error {
  ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
  defer cancel()
  _, err := s.inv.Reserve(ctx, &inventorypb.ReserveRequest{Sku: sku, Quantity: qty})
  if errors.Is(err, context.DeadlineExceeded) {
    return ErrInventoryTimeout
  }
  if status.Code(err) == codes.FailedPrecondition {
    return ErrOutOfStock
  }
  return err
}
